import {exec as run} from "node:child_process";
const command = "cat " + req.query.file;
run(command);

function build(id: string) { return "SELECT * FROM users WHERE id=" + id; }
const query = build(req.query.id);
db.query(query);

const id = req.body.id;
const query = `SELECT * FROM accounts WHERE id = ${id}`;
db.query(
 query
);

const value = location.hash;
const markup = "<p>" + value + "</p>";
document.body.innerHTML = markup;

import {readFileSync as read} from "node:fs";
const target = req.query.filename;
read(target);

import DOMPurify from "dompurify";
const safe = DOMPurify.sanitize(location.hash);
document.body.innerHTML = safe;
